sys_script.script:
(function executeRule(current, previous) {
    if (current.operation() === 'insert') {
        if (String(current.state) === '2') current.setValue('state', 1);
        return;
    }
    if (!current.state.changes() || String(current.state) !== '2') return;
    var appr = String(current.getValue('approval') || 'not_requested');
    if (appr === 'approved') return; /* post-approval advance (conversion path) */
    var engine = new PTAGApprovalEngine();
    var prevState = previous ? String(previous.getValue('state') || '-1') : '-1';
    current.setValue('state', prevState); /* hold until the decision */
    if (appr !== 'requested') {
        current.setValue('approval', 'requested');
        var who = engine.resolveApprover(current);
        if (who) current.setValue('approver', who);
        var whoName = engine.userName(who);
        current.work_notes = 'Acceptance (In Backlog) requires approval. Approval requested' +
            (whoName ? (' from ' + whoName) : ' (no approver resolvable - set Approver manually)') +
            '; the request stays in its current state until the decision.';
    } else {
        current.work_notes = 'Acceptance already awaiting approval; state unchanged until the decision.';
    }
})(current, previous);
